\",\"title\":\"TEXT 16\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3687,\"bb\":568358,\"url_path\":\"/en/library/bg/13/15/devanagari/\",\"body_final\":\"सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम् ।
असक्तं सर्वभृच्च‍ैव निर्गुणं गुणभोक्तृ च ॥ १५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3688,\"bb\":3251,\"url_path\":\"/en/library/bg/13/15/b3251/\",\"body_value\":\"sarvendriya-guṇābhāsaṁ
sarvendriya-vivarjitam
