\":\"that\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-avijñeyam\",{\"href\":\"/en/search/synonyms/?original=avijñeyam\",\"children\":[\"$\",\"em\",null,{\"children\":\"avijñeyam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"unknowable\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-dūra\",{\"href\":\"/en/search/synonyms/?original=dūra\",\"children\":[\"$\",\"em\",null,{\"children\":\"dūra\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-stham\",{\"href\":\"/en/search/synonyms/?original=stham\",\"children\":[\"$\",\"em\",null,{\"children\":\"stham\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"far away\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ca\",{\"href\":\"/en/search/synonyms/?original=ca\",\"children\":[\"$\",\"em\",null,{\"children\":\"ca\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"also\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-13\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-antike\",{\"href\":\"/en/search/synonyms/?original=antike\",\"children\":[\"$\",\"em\",null,{\"children\":\"antike\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"near\"}}],\"; \"]}],\"$L32\",\"$L33\"]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"3693-translation,3693-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L2a\",\"child-3697\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"The Supreme Truth exists outside and inside of all living beings, the moving and the nonmoving. Because He is subtle, He is beyond the power of the material senses to see or to know. Although far, far away, He is also near to all.\"}}]}]}]]]}]\n"])self.__next_f.push([1,"2f:[\"$\",\"div\",\"3693-purport,3693-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L2a\",\"child-3698\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"In Vedic literature we understand that Nārāyaṇa, the Supreme Person, is residing both outside and inside of every living entity. He is present in both the spiritual and material worlds. Although He is far, far away, still He is near to us. These are the statements of Vedic literature. \",[\"$\",\"em\",\"1\",{\"children\":\"Āsīno dūraṁ vrajati śayāno yāti sarvataḥ\"}],\" (\",[\"$\",\"em\",\"3\",{\"children\":\"Kaṭha Upaniṣad\"}],\" 1.2.21). And because He is always engaged in transcendental bliss, we cannot understand how He is enjoying His full opulence. We cannot see or understand with these material senses. Therefore in the Vedic language it is said that to understand Him our material mind and senses cannot act. But one who has purified his mind and senses by practicing Kṛṣṇa consciousness in devotional service can see Him constantly. It is confirmed in \",[\"$\",\"em\",\"5\",{\"children\":\"Brahma-saṁhitā\"}],\" that the devotee who has developed love for the Supreme God can see Him always, without cessation. And it is confirmed in \",[\"$\",\"$L20\",\"7\",{\"href\":\"/en/library/bg/11/54/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Bhagavad-gītā\"}],\" (11.54)\"]}],\" that He can be seen and understood only by devotional service. \",[\"$\",\"em\",\"9\",{\"children\":\"Bhaktyā tv ananyayā śakyaḥ.\"}]]}]}]]]}]\n"])self.__next_f.push([1,"34:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"27:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana das; Ramesta das; Prasad Buddhavarapu; Kresna Sucandra; Esekiel Jaggernauth\",\"locale\":\"en\"}],[\"$\",\"div\",null,{\"className\":\"w-full max-w-screen-xl mx-auto text-vb-normal-text mb-3\",\"children\":[[\"$\",\"a\",null,{\"target\":\"_blank\",\"rel\":\"noopener noreferrer\",\"href\":\"https://t.me/online_vedabase\",\"className\":\"text-vb-normal-text hover:text-vb-normal-text/60\",\"alt\":\"Vedabase Telegram\",\"aria-label\":\"Vedabase Telegram\",\"children\":[\"$\",\"svg\",null,{\"stroke\":\"currentColor\",\"fill\":\"currentColor\",\"strokeWidth\":\"0\",\"viewBox\":\"0 0 496 512\",\"className\":\"inline w-8 h-8 mr-4\",\"children\":[\"$undefined\",[[\"$\",\"path\",\"0\",{\"d\":\"M248 8C111 8 0 119 0 256s111 248 2